package com.tuap.backend.auth;
import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import com.tuap.backend.dominio.entidades.AuthIdentity; import com.tuap.backend.persistencia.AuthIdentityDAO;
@Service public class AuthIdentityUnlinkService { private final AuthIdentityDAO identities; private final IdentityResolver users; private final ReauthenticationService reauth; private final RefreshTokenService refresh;
 @org.springframework.beans.factory.annotation.Autowired public AuthIdentityUnlinkService(AuthIdentityDAO i,IdentityResolver u,ReauthenticationService r,RefreshTokenService f){identities=i;users=u;reauth=r;refresh=f;}
 @Transactional public void unlink(AuthenticatedUser user,AuthProvider provider,String raw){if(provider!=AuthProvider.GOOGLE&&provider!=AuthProvider.APPLE)throw new AuthIdentityConflictException();if(user==null||users.findByIdAndRole(user.userId(),user.role()).isEmpty())throw new AccountInactiveException();List<AuthIdentity> active=identities.lockActiveByUserIdAndRole(user.userId(),user.role());AuthIdentity target=active.stream().filter(i->i.getProvider()==provider).findFirst().orElseThrow(IdentityNotLinkedException::new);if(active.size()<=1)throw new CannotUnlinkLastIdentityException();reauth.consumeForUnlink(user,provider,raw);target.deactivate();identities.save(target);refresh.revokeAllForUser(user.userId(),user.role());}
}
